package chess; public final class Pieces { public static class Rook extends Piece{public Rook(Color c){super(c);}public boolean canMove(Position a,Position b,Board x){return (a.row()==b.row()||a.col()==b.col())&&x.clear(a,b);}} public static class Bishop extends Piece{public Bishop(Color c){super(c);}public boolean canMove(Position a,Position b,Board x){return Math.abs(a.row()-b.row())==Math.abs(a.col()-b.col())&&x.clear(a,b);}} public static class Queen extends Piece{public Queen(Color c){super(c);}public boolean canMove(Position a,Position b,Board x){int r=Math.abs(a.row()-b.row()),d=Math.abs(a.col()-b.col());return (r==0||d==0||r==d)&&x.clear(a,b);}} public static class Knight extends Piece{public Knight(Color c){super(c);}public boolean canMove(Position a,Position b,Board x){int r=Math.abs(a.row()-b.row()),d=Math.abs(a.col()-b.col());return r*d==2;}} }